import{_ as t,o,c as a,a2 as n}from"./chunks/framework.BN3Eol-0.js";const f=JSON.parse('{"title":"UXD-043 — /fly: the 2D view is readable on its dark canvas, fits the destination and draws only it; the HUD label/value blocks are a two-column grid; the nine moons are textured in 3D","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-043-fly-2d-seen-on-the-dark-destination-drawn-and-hud-grid.md","filePath":"uxs/decisions/UXD-043-fly-2d-seen-on-the-dark-destination-drawn-and-hud-grid.md"}'),s={name:"uxs/decisions/UXD-043-fly-2d-seen-on-the-dark-destination-drawn-and-hud-grid.md"};function i(d,e,r,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="uxd-043-—-fly-the-2d-view-is-readable-on-its-dark-canvas-fits-the-destination-and-draws-only-it-the-hud-label-value-blocks-are-a-two-column-grid-the-nine-moons-are-textured-in-3d" tabindex="-1">UXD-043 — <code>/fly</code>: the 2D view is readable on its dark canvas, fits the destination and draws only it; the HUD label/value blocks are a two-column grid; the nine moons are textured in 3D <a class="header-anchor" href="#uxd-043-—-fly-the-2d-view-is-readable-on-its-dark-canvas-fits-the-destination-and-draws-only-it-the-hud-label-value-blocks-are-a-two-column-grid-the-nine-moons-are-textured-in-3d" aria-label="Permalink to &quot;UXD-043 — `/fly`: the 2D view is readable on its dark canvas, fits the destination and draws only it; the HUD label/value blocks are a two-column grid; the nine moons are textured in 3D&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted (built; unit tests and a new e2e spec on three projects, screenshots read; not yet seen by the operator)</li><li><strong>Date</strong>: 2026-11-14 (proposed and decided)</li><li><strong>Decider</strong>: the operator, 2026-11-14 — the recommendations of <code>docs/wip/2026-11-14-slice-G2-brief.md</code> §12 approved as written (&quot;Yes on G1/2&quot;: decisions 10a, 11a, 12a, 13a, 14a)</li><li><strong>Answers</strong>: FY1, FY4 of the UX feedback plan; slice G2</li><li><strong>Builds on</strong>: <a href="./UXD-001-ui-accent-blue-replaces-teal">UXD-001</a> (no teal; <code>#889fe7</code> is the state colour of the highlighted moon), <a href="./UXD-002-type-scale-and-the-11px-floor">UXD-002</a> (the 2D labels move from 9 px to the 11 px floor)</li><li><strong>Pairs with</strong>: UXD-042 (slice G1: the Plan wiring that sends a moon flight to <code>/fly</code> with <code>mission.targetMoon</code>)</li><li><strong>Changes</strong>: <code>src/lib/fly/fly-2d-style.ts</code>, <code>fly-2d-scale.ts</code>, <code>fly-2d-targets.ts</code> (new, each with a test), <code>src/lib/three/fly-frame-runner.ts</code> (<code>draw2d</code>), <code>src/lib/three/fly-helio-scene.ts</code> (moon textures, <code>setTargetMoon</code>), <code>src/lib/three/fly-scene-host.ts</code>, <code>src/routes/fly/+page.svelte</code> (CSS of the HUD and CAPCOM rows, one wrapper), <code>src/lib/components/SpacecraftInfoCard.svelte</code>, <code>fly_2d_scale_label</code> in the 14 locale files and <code>scripts/i18n-tools/en-source-hashes.json</code>, <code>tests/e2e/fly-visuals.spec.ts</code> (new). No file under <code>static/images/</code>, <code>static/textures/</code> or <code>static/data/</code> changed; no hero, no new asset.</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><strong>FY1.</strong> <code>draw2d</code> painted on <code>#04040c</code> with 1 px rings at 0.35 alpha, stars at 0.06 to 0.22 and not-yet-flown arcs at 0.2. Composited over the background they measured: Earth ring 1.71:1, Mars ring 1.38:1, stars 1.09 to 1.62:1, future arcs 1.21:1 and 1.23:1. The view also drew Earth and Mars for every flight, at a fixed <code>min(W, H) / 4</code> px per AU: 15 of 21 heliocentric destinations were off the canvas at 1440x900 (Jupiter 1,171 px from the Sun against a 450 px half-height), and the arrival ring of a Jupiter flight was Mars-coloured. <strong>FY4.</strong> <code>.hud-row</code> was <code>display: flex; flex-wrap: wrap</code>, so a value one character too long dropped whole under its label (&quot;TRAJECTORY&quot; alone on a line, &quot;Heliocentric Hohmann&quot; under it). In 3D the nine moon destinations had textures in <code>static/textures/</code> that <code>/fly</code> never loaded.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>Neutral rings, brighter lines (10a).</strong> One const object, <code>FLY_2D_STYLE</code> in <code>src/lib/fly/fly-2d-style.ts</code>, holds every 2D line: rings (Earth, the destination, the Moon&#39;s) <code>rgba(255,255,255,0.45)</code> at 1.25 px; the LAUNCH / ARRIVAL anchor rings white at 0.7; stars alpha 0.15 to 0.51 (<code>0.15 + (i % 5) * 0.09</code>); the labels 11 px at 85 % white (were 9 px). The planet identity colour left the rings and stays on the live body, its halo and its label. <strong>Departure from the approved numbers:</strong> the approved future-arc alpha of 0.45 measures 1.82:1 (outbound <code>#5070ff</code>) and 1.91:1 (return <code>#9966ff</code>), under the same decision&#39;s 3:1 floor, so the not-yet-flown arcs are 0.75 alpha (3.19:1 outbound, 3.51:1 return). The flown arcs and the dash pattern are unchanged.</li><li><strong>The scale fits the flight (11a).</strong> <code>fitScale2d(extentAu, W, H)</code> puts the outermost of {the destination&#39;s orbit, the farthest trajectory point} at 85 % of the shorter half-extent; the extent never goes below 1.5 AU (a Venus trip does not zoom in on the Sun). The scale eases toward the fit with a 0.27 s time constant (95 % in about 0.8 s; reduced motion snaps). A readout at the bottom left draws a 1 AU bar and &quot;1 AU = N px&quot; (<code>fly_2d_scale_label</code>, parameter <code>px</code>, hand-written in 14 locales with each locale&#39;s unit symbol from the i18n style guide: au, AE, а. е., АЈ, و.ف). The phase markers use the same fitted scale. The Moon (cislunar) view keeps its own scale.</li><li><strong>Only the active destination (12a).</strong> <code>select2dTargets</code> chooses what is drawn besides Earth, the origin: the active destination (ring from <code>orbitPath</code>, live body from <code>destinationPos</code>, disc radius from <code>DEST_STYLE</code> clamped to 3.5 to 9 px, halo and label in <code>DESTINATION_LABEL_COLORS[id]</code>, label <code>destinationLabel(id)</code>); for a planetary-moon flight (<code>mission.targetMoon</code>) the host planet plus the named moon on a short ring; for a Sun-target mission no destination body. The hard-coded Mars ring, Mars disc and <code>nav_mars</code> label are gone; the arrival ring is white and sits where the trajectory ends.</li><li><strong>3D moons (13a).</strong> The nine moon destinations (Phobos, Deimos, Io, Europa, Ganymede, Callisto, Titan, Enceladus, Triton) load their existing <code>2k_&lt;id&gt;.jpg</code> when first shown or targeted (not at build, so a flight that never shows moons pays nothing). <code>setTargetMoon</code> gives the targeted moon an orbit ring in <code>#889fe7</code> at 0.9 opacity, a 1.6x body, and keeps it visible when the moon layer is off. Ceres, Vesta, Psyche and Bennu stay stylised spheres; no asset was added.</li><li><strong>A label/value grid (14a).</strong> Every label/value block in <code>/fly</code> is a two-column grid, <code>fit-content(50%) minmax(0, 1fr)</code> with a 10 px gap: the <code>.hud</code> panels (identity, navigation, flight parameters, systems; their non-row children span both columns), the spacecraft info card (<code>dl</code>), and the CAPCOM communications rows (<code>.comm-grid</code>). The row element is <code>display: contents</code>, so the label column is shared by every row of a panel, the value is left-aligned, starts in the label&#39;s row and wraps only inside its own column (a long single token still breaks anywhere). The search <code>flex-wrap</code> on <code>.hud-row</code> returns nothing; the other <code>flex-wrap</code> rules in <code>/fly</code> are engine dots, status lights and chip rows, not label/value rows. The mini HUD&#39;s <code>.mh-row</code> is three unlabelled values and the telemetry console&#39;s headings are titles, so they stay flex.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>A 2D flight to Pluto shows the Earth ring as a 10 px circle: the compression is the true picture, and the readout says so.</li><li>A moon flight&#39;s 2D moon dot circles its host at the moon&#39;s real period, so a Phobos flight spins fast at high sim speeds (the 3D moons use a wall-clock drift for this reason; 2D has no such decoupling).</li><li>The 3D moon highlight has no text label (the HUD title names the moon).</li><li><code>.hud</code> panels are grids, so <code>.hud-phase</code> uses <code>justify-self</code>, and a new non-row child of a <code>.hud</code> panel spans both columns by the <code>.hud &gt; :not(.hud-row)</code> rule.</li><li>The stars at the low end (0.15 alpha, 1.33:1) are dots for depth, not graphics the viewer needs; only the strongest stars clear 3:1.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>See the Change inventory row G2 and <code>tests/e2e/fly-visuals.spec.ts</code>. Contrast of each line over <code>#04040c</code> (relative luminance, sRGB), unit-tested in <code>fly-2d-style.test.ts</code>: ring white 0.45 4.45:1, anchor white 0.7 9.87:1, future outbound 0.75 3.19:1, future return 0.75 3.51:1, flown arcs 4.96:1 and 5.54:1, brightest star 4.21:1, faintest star 1.33:1.</p>',10)])])}const g=t(s,[["render",i]]);export{f as __pageData,g as default};
